{
  "name": "zbuild",
  "version": "0.1.0",
  "description": "Plugin-based framework for autonomous AI agent delivery pipelines.",
  "license": "MIT",
  "author": "Eric Ziegler <eric@zig.us>",
  "homepage": "https://github.com/ezigus/zBuild",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ezigus/zBuild.git"
  },
  "bugs": {
    "url": "https://github.com/ezigus/zBuild/issues"
  },
  "scripts": {
    "test": "bash tests/run-all.sh",
    "test:unit": "bash scripts/run-tests.sh --tier unit",
    "test:integration": "bash scripts/run-tests.sh --tier integration",
    "test:e2e": "bash scripts/run-tests.sh --tier e2e",
    "test:golden": "bash scripts/run-tests.sh --tier golden",
    "test:mutation": "bash scripts/run-tests.sh --tier mutation",
    "lint": "bash scripts/lib/lint-model-names.sh && shellcheck -x --severity=warning scripts/zbuild && find scripts core plugins -name '*.sh' -not -path '*/legacy-DoNotUse/*' -print0 | xargs -0 -P 6 -n 90 shellcheck -x --severity=warning && bash scripts/lib/lint-stage-io.sh && bash scripts/lib/lint-contract.sh && bash scripts/lib/lint-doc-style.sh && bash scripts/lib/lint-vision.sh && bash scripts/lib/validate-mechanics-yaml.sh && bash scripts/lib/lint-doc-freshness.sh && bash scripts/lib/lint-action-versions.sh && bash scripts/lib/lint-grep-c.sh && bash scripts/lib/lint-test-identity.sh && bash scripts/lib/lint-llm-envelope.sh && bash scripts/lib/lint-disposition-classify.sh && bash scripts/lib/lint-silenced-redirect.sh && bash scripts/lib/lint-test-errexit.sh && bash scripts/lib/lint-test-engine-state.sh && bash scripts/lib/lint-disposition-words.sh && bash scripts/lib/lint-stage-signals.sh && bash scripts/lib/lint-adr-enforced-by.sh && bash scripts/lib/lint-plain-prompts.sh && bash scripts/lib/lint-bare-timeout.sh && bash scripts/lib/lint-stage-output-names.sh && bash scripts/lib/lint-atomic-write-unchecked.sh"
  },
  "engines": {
    "bash": ">=5.0.0",
    "node": ">=20.0.0"
  },
  "keywords": [
    "ai",
    "agents",
    "pipeline",
    "claude-code",
    "plugin-framework",
    "autonomous"
  ]
}

